import csv, io
def decode(data):
    return list(csv.DictReader(io.StringIO(data)))

src/validate.py:
from decimal import Decimal, InvalidOperation
def validate(rows):
    result = []
    for row in rows:
        try:
            valid = Decimal(row["amount"]).is_finite()
        except (InvalidOperation, KeyError):
            continue
        if row.get("owner", "").strip() and valid:
            result.append(row)
    return result

src/normalize.py:
from decimal import Decimal
def normalize(rows):
    return [(r["owner"].strip().casefold(), Decimal(r["amount"])) for r in rows]

src/aggregate.py:
from decimal import Decimal
def aggregate(rows):
    result = {}
    for owner, amount in rows:
        result[owner] = result.get(owner, Decimal(0)) + amount
    return result

